
const clips = {"01-thanksgiving": "data:audio/wav;base64,", "02-harvest": "data:audio/wav;base64,", "03-turkey": "data:audio/wav;base64,", "04-pumpkin": "data:audio/wav;base64,", "05-cranberry": "data:audio/wav;base64,", "06-feast": "data:audio/wav;base64,", "07-thankful": "data:audio/wav;base64,", "08-grateful": "data:audio/wav;base64,", "09-gratitude": "data:audio/wav;base64,", "10-bless": "data:audio/wav;base64,", "11-happy-thanksgiving": "data:audio/wav;base64,", "12-i-m-grateful-for-your-help": "data:audio/wav;base64,"};
const items = [{"id": "01-thanksgiving", "text": "Thanksgiving", "ipa": "ˌθæŋksˈɡɪvɪŋ", "meaning": "感恩节", "tip": "开头的 /θ/ 要轻轻送气，别读成 /s/。", "picture": "assets/vocabulary/thanksgiving-small.png", "file": "audio/01-thanksgiving.wav"}, {"id": "02-harvest", "text": "harvest", "ipa": "ˈhɑːrvɪst", "meaning": "收获；丰收", "tip": "从秋日丰收，想到一年里的成长与收获。", "picture": "assets/vocabulary/harvest-small.png", "file": "audio/02-harvest.wav"}, {"id": "03-turkey", "text": "turkey", "ipa": "ˈtɝːki", "meaning": "火鸡", "tip": "美国感恩节餐桌上的代表性食物。", "picture": "assets/vocabulary/turkey-small.png", "file": "audio/03-turkey.wav"}, {"id": "04-pumpkin", "text": "pumpkin", "ipa": "ˈpʌmpkɪn", "meaning": "南瓜", "tip": "做成南瓜派，是常见的节日甜点。", "picture": "assets/vocabulary/pumpkin-small.png", "file": "audio/04-pumpkin.wav"}, {"id": "05-cranberry", "text": "cranberry", "ipa": "ˈkrænberi", "meaning": "蔓越莓", "tip": "酸甜的蔓越莓酱，常用来搭配火鸡。", "picture": "assets/vocabulary/cranberry-small.png", "file": "audio/05-cranberry.wav"}, {"id": "06-feast", "text": "feast", "ipa": "fiːst", "meaning": "盛宴", "tip": "形容一顿丰盛的大餐。", "picture": "assets/vocabulary/feast-small.png", "file": "audio/06-feast.wav"}, {"id": "07-thankful", "text": "thankful", "ipa": "ˈθæŋkfəl", "meaning": "感激的；心怀感谢的", "tip": "想到值得感谢的人和事，就可以用上它。", "picture": "assets/vocabulary/thankful-small.png", "file": "audio/07-thankful.wav"}, {"id": "08-grateful", "text": "grateful", "ipa": "ˈɡreɪtfəl", "meaning": "感激的", "tip": "常用来表达对他人帮助的感谢。", "picture": "assets/vocabulary/grateful-small.png", "file": "audio/08-grateful.wav"}, {"id": "09-gratitude", "text": "gratitude", "ipa": "ˈɡrætətuːd", "meaning": "感激之情；感恩", "tip": "这是名词；前面两个词是形容词。", "picture": "assets/vocabulary/gratitude-small.png", "file": "audio/09-gratitude.wav"}, {"id": "10-bless", "text": "bless", "ipa": "bles", "meaning": "祝福；保佑（动词）", "tip": "为他人祈愿平安与幸福。", "picture": "assets/vocabulary/bless-small.png", "file": "audio/10-bless.wav"}, {"id": "11-happy-thanksgiving", "text": "Happy Thanksgiving!", "ipa": "ˈhæpi ˌθæŋksˈɡɪvɪŋ", "meaning": "感恩节快乐！", "tip": "", "picture": null, "file": "audio/11-happy-thanksgiving.wav"}, {"id": "12-i-m-grateful-for-your-help", "text": "I'm grateful for your help.", "ipa": "aɪm ˈɡreɪtfəl fər jʊr help", "meaning": "谢谢你的帮助。", "tip": "", "picture": null, "file": "audio/12-i-m-grateful-for-your-help.wav"}];
const player = new Audio();
const status = document.getElementById('status');
let queue = [];
function clearActive() { document.querySelectorAll('.playing').forEach(el => el.classList.remove('playing')); }
function stop() { queue = []; player.pause(); player.currentTime = 0; clearActive(); status.textContent = '已停止。'; }
function playNext() {
  if (!queue.length) { clearActive(); status.textContent = '播放完毕，再跟读一遍吧。'; return; }
  const id = queue.shift(); const item = items.find(i => i.id === id);
  clearActive(); document.getElementById(id).classList.add('playing');
  player.src = clips[id]; player.playbackRate = Number(document.getElementById('rate').value);
  status.textContent = '正在播放：' + item.text;
  player.play().catch(() => { queue = []; clearActive(); status.textContent = '播放未成功，请再次点击发音按钮，或检查浏览器的音频设置。'; });
}
document.querySelectorAll('[data-id]').forEach(button => button.addEventListener('click', () => { stop(); queue = [button.dataset.id]; playNext(); }));
document.getElementById('play-all').addEventListener('click', () => { stop(); queue = items.slice(0, 10).map(i => i.id); playNext(); });
document.getElementById('stop').addEventListener('click', stop);
document.getElementById('rate').addEventListener('change', event => { player.playbackRate = Number(event.target.value); });
player.addEventListener('ended', playNext);
player.addEventListener('error', () => { queue = []; clearActive(); status.textContent = '音频读取失败，请重新打开完整的HTML文件。'; });
